    // for common item sizes (e.g., < 10) unless they are exactly 0.
    if post > 0.0 && post < 10.0 {
        score += 20.0;
    }

    // Lookahead logic: If next_item_size is known, penalize bins that 
    // leave a residual too small to accommodate the next item.
    if next > 0.0 && post < next {
        score += (next - post) * 1.5;
    }

    // New bin avoidance: Heavily penalize opening a new bin unless the current
    // fitting options are extremely poor (i.e., they create high dead space).
    if bin_residual == bin_capacity {
