        score -= 25.0;
    }

    // 4. Harmonic thresholding:
    // If the post_residual is a clean divisor of the capacity, it's often a good state.
    if bin_capacity % (post_residual + 1) == 0 {
        score -= 10.0;
    }

    // 5. Progression awareness:
    // As the stream nears the end, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && fitting_bins_count > 0 {
        // If we are late in the stream, avoid opening new bins (bin_residual == bin_capacity)
