pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual, heavily weight perfect fits.
    // Use a sharper curve for residuals to favor immediate tight packing.
    let mut score = post_res * 1.1;

    // Targeted Fragmentation penalty:
    // Small gaps are expensive; penalize gaps that are too small to fit common items (approx 1-12).
    if post_residual > 0 && post_residual < 14 {
        score += (22.0 - post_res) * (1.3 - progress * 0.4);
    }

    // Lookahead coupling: Anticipate the next item.
    // If the next item won't fit in the current residual, penalize the bin proportional to the 'miss'.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res) * (1.8 + progress * 1.2);
    }

    // New Bin Gatekeeping:
    // Balance the cost of opening a new bin vs. stuffing an existing one.
    if is_new_bin {
        // Higher cost to open a new bin as we progress to force consolidation.
        let base_new_bin_cost = 52.0 + (progress * 15.0);
        // If we have very few fitting bins, opening a new bin is less penalized.
        let availability_bonus = (fitting_bins_count as f64).min(3.0) * 8.0;
        // Reward opening if the current mean_residual is very low (system is tight).
        let tightness_bonus = (mean_residual - 8.0).max(0.0) * 1.5;

        score = base_new_bin_cost - availability_bonus - tightness_bonus;
    } else {
        // For existing bins, prioritize those that keep the residual close to the current mean.
        // This ensures the packing distribution remains uniform.
        let density_deviation = (post_res - mean_residual).abs();
        score += density_deviation * 0.35;

        // Bonus for perfect fits
        if post_residual == 0 {
            score -= 22.0;
        }
    }

    // Dynamic Pressure:
    // If we have many bins open, penalize them exponentially to encourage closing/filling them.
    if open_bins_count > 5 {
        score += ((open_bins_count as f64 - 5.0).powf(1.15)) * (1.0 + progress * 2.0);
    }

    // Emergency override: If this is the only bin that fits the item, 
    // force its selection to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    score
}

