pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor post_residual, but normalize by capacity to handle varying bin sizes
    let mut score = post_residual as f64;

    // Fragmentation penalty: Aggressively avoid "sliver" gaps that are too small for future items
    // If post_residual is small but not zero, it's a wasted space liability.
    if post_residual > 0 {
        let sliver_penalty = if post_residual < 15 { 45.0 } else { 10.0 };
        score += sliver_penalty * (1.0 - progress * 0.5);
    }

    // Dynamic Lookahead: 
    // If next_item_size cannot fit in the current post_residual, penalize the bin.
    // We scale this penalty by the current open_bins_count to encourage consolidation.
    if post_residual < next_item_size {
        let lookahead_penalty = 35.0 * (1.0 - progress);
        score += lookahead_penalty * (1.0 + (open_bins_count as f64 / 20.0));
    }

    // New Bin Gatekeeping:
    // Increased threshold for opening new bins to force better consolidation in late stages.
    if is_new_bin {
        let base_new_bin_cost = 65.0 * (1.0 - progress).powf(0.75);
        let efficiency_bonus = (mean_residual - (bin_capacity as f64 * 0.15)).max(0.0) * 1.2;
        score += (base_new_bin_cost - efficiency_bonus).max(8.0);
    }

    // Density consistency:
    // Penalize bins that deviate from the mean_residual to prevent sparse "outlier" bins.
    let density_deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.6 * density_deviation * (progress.sqrt());

    // Perfect fit reward: significantly lower score for complete utilization
    if post_residual == 0 {
        score -= 22.0;
    }

    // Saturation pressure:
    // If we have many open bins, prioritize those that are nearly full to close them out.
    if open_bins_count > 8 {
        let fullness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= fullness * 15.0;
    }

    score
}
